SELECT "sbond_3"."id", "canc"."drug_id", "sbond_7"."atomid_2", "sbond_7"."atomid_2", "canc"."class", MAX("sbond_7"."id"), MAX("sbond_3"."id"), AVG("sbond_7"."id")
FROM "sbond_3" JOIN "canc" ON "sbond_3"."drug" = "canc"."drug_id" LEFT JOIN "sbond_7" ON "canc"."drug_id" = "sbond_7"."drug" WHERE "canc"."drug_id" = 'd177                                                                                                ' AND "sbond_7"."atomid" LIKE '%d171_4                                                                                              %' AND "sbond_7"."id" != 3049 AND "sbond_7"."atomid_2" LIKE '%d86b_10                                                                                             %' AND "sbond_3"."atomid" = 'd262_3                                                                                              ' GROUP BY "sbond_3"."id", "canc"."drug_id", "sbond_7"."atomid_2", "sbond_7"."atomid_2", "canc"."class" HAVING MAX("sbond_3"."id") > 21;

SELECT "atom"."atomid", "atom"."atomtype", "sbond_2"."id", "sbond_2"."id", AVG("sbond_1"."id"), COUNT("sbond_1"."id")
FROM "sbond_1" LEFT JOIN "atom" ON "sbond_1"."atomid" = "atom"."atomid" JOIN "sbond_2" ON "atom"."atomid" = "sbond_2"."atomid_2" WHERE "atom"."atomid" LIKE '%d324_17                                                                                             %' AND "atom"."name" = 'ti' AND "atom"."atomid" = 'd177_47                                                                                             ' AND "sbond_2"."atomid" != 'd197_40                                                                                             ' AND "sbond_2"."atomid" = 'd27_20                                                                                              ' GROUP BY "atom"."atomid", "atom"."atomtype", "sbond_2"."id", "sbond_2"."id" HAVING COUNT("sbond_1"."id") > 11 ORDER BY "atom"."atomid" ASC, "sbond_2"."id" ASC;

SELECT "sbond_3"."atomid", "atom"."charge", "sbond_3"."atomid", MAX("sbond_3"."id"), MAX("sbond_3"."id")
FROM "sbond_3" JOIN "canc" ON "sbond_3"."drug" = "canc"."drug_id" LEFT JOIN "atom" ON "sbond_3"."atomid_2" = "atom"."atomid" WHERE "canc"."drug_id" LIKE '%d85_1                                                                                               %' AND "sbond_3"."id" > 2 AND "canc"."drug_id" LIKE '%d207                                                                                                %' AND "sbond_3"."drug" = 'd262                                                                                                ' GROUP BY "sbond_3"."atomid", "atom"."charge", "sbond_3"."atomid" LIMIT 586;

SELECT "sbond_7"."drug", "atom"."atomid", "sbond_7"."atomid", COUNT("sbond_7"."id")
FROM "sbond_7" JOIN "atom" ON "sbond_7"."atomid_2" = "atom"."atomid" WHERE "atom"."drug" != 'd39                                                                                                 ' AND "atom"."atomid" LIKE '%d324_17                                                                                             %' AND "sbond_7"."atomid_2" != 'd4_6                                                                                                ' GROUP BY "sbond_7"."drug", "atom"."atomid", "sbond_7"."atomid" HAVING COUNT("sbond_7"."id") > 91;

